/**
 * A SYNTHETIC example sequence for the "Load example" button.
 *
 * This is not a real gene or genome region. It is generated by code so that
 * it is honest (no invented "real" data) and shows every feature of the
 * analyzer at a glance:
 *   - an average region (~42% GC)
 *   - a GC-rich region (~68% GC)
 *   - a run of N (unknown bases), which becomes a gap in the chart
 *   - an AT-rich region (~28% GC)
 *
 * It is generated from a fixed seed, so it is identical every time.
 * To use real data instead, replace EXAMPLE_FASTA with any single FASTA record.
 */

/** Small seeded random number generator (mulberry32): same seed, same numbers. */
function seededRandom(seed: number): () => number {
  let state = seed
  return () => {
    state = (state + 0x6d2b79f5) | 0
    let t = Math.imul(state ^ (state >>> 15), 1 | state)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** Regions of the example: how many bases, and the chance each base is G or C. */
const REGIONS: { length: number; gcProbability: number | 'N' }[] = [
  { length: 600, gcProbability: 0.42 },
  { length: 400, gcProbability: 0.68 },
  { length: 150, gcProbability: 'N' },
  { length: 500, gcProbability: 0.28 },
  { length: 350, gcProbability: 0.45 },
]

function generateExampleSequence(): string {
  const random = seededRandom(20261120)
  let sequence = ''
  for (const region of REGIONS) {
    for (let i = 0; i < region.length; i++) {
      if (region.gcProbability === 'N') {
        sequence += 'N'
      } else if (random() < region.gcProbability) {
        sequence += random() < 0.5 ? 'G' : 'C'
      } else {
        sequence += random() < 0.5 ? 'A' : 'T'
      }
    }
  }
  return sequence
}

/** Split a sequence into FASTA-style lines of 60 bases. */
function wrapLines(sequence: string, width = 60): string {
  const lines: string[] = []
  for (let i = 0; i < sequence.length; i += width) lines.push(sequence.slice(i, i + width))
  return lines.join('\n')
}

export const EXAMPLE_NAME = 'Synthetic example (GC-rich region, N gap, AT-rich region)'

/** The example as FASTA text, exactly as if the user had pasted it. 2,000 bases. */
export const EXAMPLE_FASTA = `>${EXAMPLE_NAME}\n${wrapLines(generateExampleSequence())}\n`
